-- M1 第三块 PR1：对话会话与消息（FR-14）。
-- Create "conversations" table
CREATE TABLE "conversations" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "created_at" timestamptz NOT NULL, "updated_at" timestamptz NOT NULL, "org_id" bigint NOT NULL, "user_id" bigint NOT NULL, "title" character varying NOT NULL DEFAULT '', "model_id" bigint NULL, "deleted_at" timestamptz NULL, PRIMARY KEY ("id"));
-- Create index "conversation_user_id_updated_at" to table: "conversations"
CREATE INDEX "conversation_user_id_updated_at" ON "conversations" ("user_id", "updated_at");
-- Create "messages" table
CREATE TABLE "messages" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "created_at" timestamptz NOT NULL, "updated_at" timestamptz NOT NULL, "role" character varying NOT NULL, "content" text NOT NULL DEFAULT '', "status" character varying NOT NULL DEFAULT 'done', "model_name" character varying NOT NULL DEFAULT '', "fallback_from" character varying NOT NULL DEFAULT '', "error_code" character varying NOT NULL DEFAULT '', "error" character varying NOT NULL DEFAULT '', "prompt_tokens" bigint NOT NULL DEFAULT 0, "completion_tokens" bigint NOT NULL DEFAULT 0, "request_id" character varying NOT NULL DEFAULT '', "conversation_id" bigint NOT NULL, PRIMARY KEY ("id"), CONSTRAINT "messages_conversations_messages" FOREIGN KEY ("conversation_id") REFERENCES "conversations" ("id") ON UPDATE NO ACTION ON DELETE NO ACTION);
-- Create index "message_conversation_id_id" to table: "messages"
CREATE INDEX "message_conversation_id_id" ON "messages" ("conversation_id", "id");
